import { AgentContext } from '../../../domain/core/agents/agentContext';
import { expect, it, vi } from 'vitest';
import { AgentChatService } from './agentChatService';
import { GenerationCanvasBridge } from './generationCanvasBridge';
import type { ChatStore, ChatTools, ChatMcpBinding, CodexConnection, CodexMessage } from './ports';
import type { ChatSession } from '../../../domain/mapping/agent-chat/agentChat';
import type { CanvasSessionPort } from '../agent/ports';
import { MappingDocumentController } from '../../../domain/mapping/workspace/mappingDocumentController';
import { initialCanvasState } from '../../../domain/mapping/workspace/mappingWorkspace';
import { singleDiagramScene } from '../../../domain/core/diagrams/projectDiagramCanvas';
import { documentFromHistory, validateCanvasHistory } from '../../../domain/core/diagrams/canvasHistory';

async function fixture(contextLibrary?: ConstructorParameters<typeof AgentChatService>[7]) {
  const c = new MappingDocumentController({ scene: singleDiagramScene('Original'), edges: [], sections: {} }, initialCanvasState());
  const viewId = c.canvasView(0, { operation: 'create', name: 'A' }).activeViewId!;
  const receipts = new Map<string, unknown>();
  const live: CanvasSessionPort = { register() {}, list: () => [{ canvasId: 'live', stableWorkspaceId: 'stable', documents: [{ documentId: 'doc', name: 'A' }] }],
    poll: async () => [], reply() {}, unregister() {}, dispose() {},
    async dispatch(_id, command) {
      if (command.method === 'identity') return { version: c.getSnapshot().version };
      const p = command.payload as any;
      if (command.method !== 'canvas-generation') throw Error('Unexpected command');
      if (receipts.has(p.requestId)) return receipts.get(p.requestId);
      const result = p.operation === 'start' ? c.startGeneration(p.expectedVersion, p.viewId, p.candidates, p.history) : c.updateGeneration(p.viewId, p.generation, p.history);
      receipts.set(p.requestId, result); return result;
    } };
  const bridge = new GenerationCanvasBridge(live), saved = new Map<string, ChatSession>();
  const store: ChatStore = { list: async () => [...saved.values()], save: async s => { saved.set(s.id, structuredClone(s)); } };
  let notify: (event: CodexMessage) => void = () => {}, serial = 0;
  const requests: { method: string; params: Record<string, any> }[] = [], replies: unknown[] = [];
  const connection: CodexConnection = { async request<T>(method: string, params: Record<string, any>): Promise<T> {
    requests.push({ method, params });
    if (method === 'thread/start' || method === 'thread/fork') return { thread: { id: `thread-${++serial}` }, model: 'model-x', reasoningEffort: 'high' } as T;
    if (method === 'turn/start') { const id = `turn-${++serial}`; notify({ method: 'turn/started', params: { threadId: params.threadId, turn: { id } } }); return { turn: { id } } as T; }
    return {} as T;
  }, respond: (_id, result) => replies.push(result), reject() {}, subscribe(listener) { notify = listener; return () => {}; }, dispose() {} };
  const tools: ChatTools = { definitions: [{ type: 'function', name: 'gen-alternatives', description: 'Generate', inputSchema: {} }, { type: 'function', name: 'edit-diagram', description: 'Edit', inputSchema: {} }], call: vi.fn() };
  const mcp: ChatMcpBinding = { chatId: token => token, setOrigin() {}, config: id => ({ binding: id }), bind: vi.fn(), clear: vi.fn() };
  const service = new AgentChatService(connection, store, '/workspace', undefined, tools, mcp, bridge, contextLibrary);
  const parent = await service.create({ model: 'model-x', effort: 'high', sandbox: 'workspace-write' });
  await service.send(parent.id, { text: 'Try three different layouts exactly as described.', model: 'model-x', effort: 'high', sandbox: 'workspace-write', requestId: crypto.randomUUID(), canvas: { workspaceInstanceId: 'live', documentId: 'doc' } });
  const input = { viewId, prompt: 'Explore layouts', alternatives: [1, 2, 3].map(i => ({ name: `A.${i}`, prompt: `Layout ${i}` })), requestId: 'generation' };
  return { c, viewId, bridge, store, saved, service, parent, input, requests, tools, mcp, replies, live, connection, notify: (event: CodexMessage) => notify(event) };
}
it('runs children concurrently with inherited configuration and tools, isolates edits, attributes usage, and publishes without changing the live canvas', async () => {
  const f = await fixture();
  try {
    const before = f.c.getSnapshot().canvasRevisionId;
    const group = await f.service.genAlternatives(f.parent.id, f.input);
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(4));
    const children = await Promise.all(group.candidates.map(candidate => f.service.get(candidate.chatId)));
    expect(children.every(child => child.status === 'running')).toBe(true); // None must finish before others start.
    expect(f.requests.filter(r => r.method === 'thread/fork')).toHaveLength(3);
    for (const request of f.requests.filter(r => r.method === 'thread/fork')) expect(request.params).toMatchObject({
      threadId: f.parent.threadId, beforeTurnId: (await f.service.get(f.parent.id)).turnId, model: 'model-x', config: { model_reasoning_effort: 'high' } });
    for (const child of children) {
      expect(child.settings).toEqual({ model: 'model-x', effort: 'high', sandbox: 'workspace-write' });
      expect(await f.service.toolDefinitions(child.id)).toEqual(f.tools.definitions);
      expect(child.generation!.metadata.triggerPrompt).toBe('Try three different layouts exactly as described.');
      await expect(f.service.genAlternatives(child.id, { ...f.input, requestId: 'nested' })).rejects.toThrow('nested');
    }
    expect(await f.service.genAlternatives(f.parent.id, f.input)).toEqual(group);
    expect(f.requests.filter(r => r.method === 'thread/fork')).toHaveLength(3);
    await expect(f.service.genAlternatives(f.parent.id, { ...f.input, prompt: 'Different' })).rejects.toThrow('REQUEST_ID_CONFLICT');
    for (let i = 0; i < children.length; i++) {
      const child = children[i], canvas = child.canvasContext!.canvas!;
      await f.bridge.dispatch(canvas.workspaceInstanceId, { method: 'apply', documentId: canvas.documentId, payload: { requestId: 'edit', expectedVersion: 0,
        operations: [{ method: 'replace', nodeId: 'grid:overview', ascii: `Candidate ${i}` }] } });
      const last = { totalTokens: 30, inputTokens: 20, cachedInputTokens: 5, outputTokens: 10, reasoningOutputTokens: 3 };
      const total = Object.fromEntries(Object.entries(last).map(([key, value]) => [key, value + 100]));
      f.notify({ method: 'thread/tokenUsage/updated', params: { threadId: child.threadId, turnId: child.turnId, tokenUsage: { total, last } } });
      f.notify({ method: 'thread/tokenUsage/updated', params: { threadId: child.threadId, turnId: child.turnId, tokenUsage: { total, last } } });
      f.notify({ method: 'turn/completed', params: { threadId: child.threadId, turn: { id: child.turnId, status: 'completed' } } });
    }
    await vi.waitFor(() => expect(group.candidates.every(candidate => f.c.canvasViews().saved[candidate.viewId].generation?.status === 'finished')).toBe(true));
    expect(f.c.getSnapshot().canvasRevisionId).toBe(before);
    expect(f.c.getSnapshot().document.scene.contents.overview.content.ascii).toBe('Original');
    for (let i = 0; i < children.length; i++) {
      const view = f.c.canvasViews().saved[group.candidates[i].viewId];
      expect(view.generation!.usage!.totalTokens).toBe(30);
      expect(view.generation!.durationMs).toBeGreaterThanOrEqual(0);
      expect(documentFromHistory(f.c.exportHistory(), view.finalCheckpointId).scene.contents.overview.content.ascii).toBe(`Candidate ${i}`);
    }
    validateCanvasHistory(f.c.exportHistory());
  } finally { f.service.dispose(); }
});
it('cancels child generations and locks unfinished candidates against manual modification', async () => {
  const f = await fixture();
  try {
    const group = await f.service.genAlternatives(f.parent.id, f.input);
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(4));
    expect(() => f.c.canvasView(f.c.getSnapshot().version, { operation: 'open', viewId: group.candidates[0].viewId })).toThrow('still generating');
    expect(() => f.c.canvasView(f.c.getSnapshot().version, { operation: 'discard', viewId: f.viewId })).toThrow('cancel');
    await f.service.interrupt(f.parent.id);
    expect(group.candidates.every(candidate => f.c.canvasViews().saved[candidate.viewId].generation?.status === 'cancelled')).toBe(true);
    expect(f.requests.filter(r => r.method === 'turn/interrupt')).toHaveLength(4);
    expect(f.bridge.list().filter(canvas => canvas.canvasId.startsWith('generation-'))).toHaveLength(0);
  } finally { f.service.dispose(); }
});

it('dispatches the native generation tool and contains a failed child without affecting siblings', async () => {
  const f = await fixture();
  try {
    f.notify({ id: 'native-call', method: 'item/tool/call', params: { threadId: f.parent.threadId,
      turnId: (await f.service.get(f.parent.id)).turnId, tool: 'gen-alternatives', arguments: f.input } });
    await vi.waitFor(() => expect(f.replies).toHaveLength(1));
    const reply = f.replies[0] as { success: boolean; contentItems: { text: string }[] };
    expect(reply.success).toBe(true);
    const group = JSON.parse(reply.contentItems[0].text);
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(4));
    expect(f.requests.filter(r => r.method === 'thread/goal/clear')).toHaveLength(3);
    const child = await f.service.get(group.candidates[0].chatId);
    f.notify({ method: 'turn/completed', params: { threadId: child.threadId, turn: { id: child.turnId, status: 'failed', error: { message: 'Provider unavailable' } } } });
    await vi.waitFor(() => expect(f.c.canvasViews().saved[group.candidates[0].viewId].generation?.status).toBe('failed'));
    expect(f.c.canvasViews().saved[group.candidates[0].viewId].generation?.error).toBe('Provider unavailable');
    expect(f.c.canvasViews().saved[group.candidates[1].viewId].generation?.status).toBe('generating');
    await expect(f.service.send(child.id, {})).rejects.toThrow('retained for review');
    await expect(f.service.readCanvas(child.id, {})).rejects.toThrow('retained for review');
    await f.service.interrupt(f.parent.id);
  } finally { f.service.dispose(); }
});
it('retains a completed result while the source is offline and publishes it once on reconnect', async () => {
  const f = await fixture();
  try {
    const group = await f.service.genAlternatives(f.parent.id, { ...f.input, alternatives: [f.input.alternatives[0]] });
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(2));
    const child = await f.service.get(group.candidates[0].chatId), canvas = child.canvasContext!.canvas!;
    await f.bridge.dispatch(canvas.workspaceInstanceId, { method: 'apply', documentId: canvas.documentId, payload: { requestId: 'edit', expectedVersion: 0,
      operations: [{ method: 'replace', nodeId: 'grid:overview', ascii: 'Retained result' }] } });
    const dispatch = f.live.dispatch.bind(f.live);
    f.live.dispatch = async () => { throw Error('Browser disconnected'); };
    f.notify({ method: 'turn/completed', params: { threadId: child.threadId, turn: { id: child.turnId, status: 'completed' } } });
    await vi.waitFor(() => expect(f.bridge.list()).toHaveLength(1));
    const source = { workspaceInstanceId: 'live', documentId: 'doc' };
    expect((await f.service.generations(source))[0]).toMatchObject({ status: 'finished', pendingSave: true });
    expect(f.saved.get(child.id)!.generation!.history).toBeDefined();
    f.live.dispatch = dispatch;
    expect((await f.service.generations(source))[0]).toMatchObject({ status: 'finished', pendingSave: false });
    const endpoint = f.c.canvasViews().saved[group.candidates[0].viewId].finalCheckpointId;
    expect(documentFromHistory(f.c.exportHistory(), endpoint).scene.contents.overview.content.ascii).toBe('Retained result');
    await f.service.generations(source);
    expect(f.c.canvasViews().saved[group.candidates[0].viewId].finalCheckpointId).toBe(endpoint);
    expect(f.requests.filter(r => r.method === 'thread/fork')).toHaveLength(1);
  } finally { f.service.dispose(); }
});
it('marks interrupted generations failed on server restart without launching replacement turns', async () => {
  const f = await fixture();
  let restarted: AgentChatService | undefined;
  try {
    const group = await f.service.genAlternatives(f.parent.id, { ...f.input, alternatives: [f.input.alternatives[0]] });
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(2));
    // Read persisted sessions as if the previous process had exited abruptly.
    restarted = new AgentChatService(f.connection, f.store, '/workspace', undefined, f.tools, f.mcp, f.bridge);
    const child = await restarted.get(group.candidates[0].chatId);
    expect(child.generation!.metadata.status).toBe('failed');
    expect(child.generation!.metadata.error).toContain('Server restarted');
    await restarted.generations({ workspaceInstanceId: 'live', documentId: 'doc' });
    expect(f.c.canvasViews().saved[group.candidates[0].viewId].generation?.status).toBe('failed');
    expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(2);
  } finally { restarted?.dispose(); f.service.dispose(); }
});

it('uses an explicit saved context in fresh parallel threads with caller tools/settings and pins provenance', async () => {
  const snapshot = AgentContext.fromMessages('saved-session', [{ role: 'user', content: [{ type: 'text', text: 'Reusable codebase facts' }], timestamp: 0 }]).toSnapshot();
  const agentContextId = `saved-agent-context-${crypto.randomUUID()}`;
  const read = vi.fn(async () => ({ agentContextId, snapshot, contentHash: snapshot.contentHash, name: 'Facts', description: '', createdAt: new Date().toISOString(), messageCount: 1, source: snapshot.source }));
  const f = await fixture({ read });
  try {
    // Definitions added after the parent started must not leak into its children.
    const inheritedTools = structuredClone(f.tools.definitions);
    f.tools.definitions.push({ type: 'function', name: 'later-tool', description: 'New', inputSchema: {} });
    const input = { ...f.input, agentContextId };
    const group = await f.service.genAlternatives(f.parent.id, input);
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(4));
    expect(f.requests.filter(r => r.method === 'thread/fork')).toHaveLength(0);
    const starts = f.requests.filter(r => r.method === 'thread/start').slice(1);
    expect(starts).toHaveLength(3);
    for (const { params } of starts) expect(params).toMatchObject({ model: 'model-x', config: { model_reasoning_effort: 'high' }, dynamicTools: inheritedTools });
    const seeds = f.requests.filter(r => r.method === 'thread/inject_items');
    expect(seeds).toHaveLength(3);
    for (const { params } of seeds) {
      expect(JSON.stringify(params)).toContain('Reusable codebase facts');
      expect(JSON.stringify(params)).not.toContain('Try three different layouts exactly as described.');
    }
    for (const candidate of group.candidates) {
      const child = await f.service.get(candidate.chatId);
      expect(child.items.find(item => item.kind === 'user')!.text).not.toContain('Try three different layouts exactly as described.');
      expect(child.items.find(item => item.kind === 'user')!.text).toContain('Explore layouts');
      expect(child.generation!.metadata).toMatchObject({ agentContextId, agentContextHash: snapshot.contentHash });
      expect(f.c.canvasViews().saved[candidate.viewId].generation).toMatchObject({ agentContextId, agentContextHash: snapshot.contentHash });
      expect(await f.service.toolDefinitions(child.id)).toEqual(inheritedTools);
    }
    expect(await f.service.genAlternatives(f.parent.id, input)).toEqual(group);
    expect(read).toHaveBeenCalledOnce();
    expect(f.requests.filter(r => r.method === 'thread/start')).toHaveLength(4);
    await f.service.interrupt(f.parent.id);
  } finally { f.service.dispose(); }
});
it('rejects a missing saved context before creating candidates or launching models', async () => {
  const f = await fixture({ read: async () => { throw Error('AGENT_CONTEXT_NOT_FOUND'); } });
  try {
    const before = f.c.exportHistory();
    await expect(f.service.genAlternatives(f.parent.id, { ...f.input, agentContextId: `saved-agent-context-${crypto.randomUUID()}` })).rejects.toThrow('AGENT_CONTEXT_NOT_FOUND');
    expect(f.c.exportHistory()).toEqual(before);
    expect(await f.service.list()).toHaveLength(1);
    expect(f.requests.filter(r => r.method === 'thread/start')).toHaveLength(1);
    expect(f.requests.filter(r => r.method === 'thread/fork')).toHaveLength(0);
  } finally { f.service.dispose(); }
});
it('does not launch a turn when cancelled while saved context is being injected', async () => {
  const snapshot = AgentContext.fromMessages('saved-session', [{ role: 'user', content: [{ type: 'text', text: 'Facts' }], timestamp: 0 }]).toSnapshot();
  const agentContextId = `saved-agent-context-${crypto.randomUUID()}`;
  const f = await fixture({ read: async () => ({ agentContextId, snapshot, contentHash: snapshot.contentHash, name: 'Facts', description: '', createdAt: new Date().toISOString(), messageCount: 1, source: snapshot.source }) });
  const request = f.connection.request.bind(f.connection);
  let release!: () => void, injecting = false;
  const pending = new Promise<void>(resolve => { release = resolve; });
  f.connection.request = async <T>(method: string, params: Record<string, unknown>) => {
    if (method === 'thread/inject_items') { injecting = true; await pending; }
    return request<T>(method, params);
  };
  try {
    const group = await f.service.genAlternatives(f.parent.id, { ...f.input, alternatives: [f.input.alternatives[0]], agentContextId });
    await vi.waitFor(() => expect(injecting).toBe(true));
    await f.service.cancelGeneration(group.candidates[0].chatId);
    release();
    await vi.waitFor(() => expect(f.requests.some(r => r.method === 'thread/inject_items')).toBe(true));
    expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(1);
    expect((await f.service.get(group.candidates[0].chatId)).generation!.metadata.status).toBe('cancelled');
    expect(f.c.canvasViews().saved[group.candidates[0].viewId].generation!.status).toBe('cancelled');
  } finally { release(); f.service.dispose(); }
});

it('injects resolved source text while pinning the compact saved-context hash in generation metadata', async () => {
  const snapshot = AgentContext.fromMessages('source-context', [{ role: 'user', timestamp: 0, content: [{
    type: 'sourceRange', sourceId: 'source', path: 'code.ts', startLine: 1, endLine: 1,
    version: { kind: 'snapshot', contentHash: 'a'.repeat(64) }
  }] }]).toSnapshot();
  const resolvedSnapshot = (await AgentContext.fromSnapshot(snapshot).resolveSources(async () => 'code.ts:1-1\nconst pinned = 42;')).toSnapshot();
  const agentContextId = `saved-agent-context-${crypto.randomUUID()}`;
  const f = await fixture({ read: async () => ({ agentContextId, snapshot, resolvedSnapshot, contentHash: snapshot.contentHash,
    name: 'Source', description: '', createdAt: new Date().toISOString(), messageCount: 1, source: snapshot.source }) });
  try {
    const group = await f.service.genAlternatives(f.parent.id, { ...f.input, alternatives: [f.input.alternatives[0]], agentContextId });
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'thread/inject_items')).toHaveLength(1));
    const injected = JSON.stringify(f.requests.find(r => r.method === 'thread/inject_items')!.params);
    expect(injected).toContain('const pinned = 42;');
    expect(injected).toContain(snapshot.contentHash);
    expect(injected).not.toContain('sourceRange');
    expect((await f.service.get(group.candidates[0].chatId)).generation!.metadata.agentContextHash).toBe(snapshot.contentHash);
  } finally { f.service.dispose(); }
});

it('adapts all eight legacy candidates and 50k prompts into Evals without changing inherited execution or retry IDs', async () => {
  const { mkdtemp, rm } = await import('node:fs/promises');
  const { tmpdir } = await import('node:os');
  const { join } = await import('node:path');
  const { LegacyGenerationAdapter } = await import('../evals/legacyGenerationAdapter');
  const { AgentContextLibrary } = await import('../agent/agentContextLibrary');
  const { FileAgentContextRepository } = await import('../../../infrastructure/core/persistence/fileAgentContextRepository');
  const { CanvasCatalogStore } = await import('../../../infrastructure/core/persistence/canvasCatalogStore');
  const root = await mkdtemp(join(tmpdir(), 'legacy-evals-')), f = await fixture();
  const records = new Map<string, import('../../../domain/mapping/evals/evalRun').EvalRun>();
  const store = { list: async () => [...records.values()], read: async (id: string) => records.get(id) ?? null,
    save: async (run: import('../../../domain/mapping/evals/evalRun').EvalRun) => { records.set(run.id, structuredClone(run)); }, delete: async (id: string) => { records.delete(id); } };
  const contexts = new AgentContextLibrary(new FileAgentContextRepository(root)), catalogs = new CanvasCatalogStore(root);
  const projects = { loadProject: async () => ({ id: 'test', repositories: [] }), projectCatalogs: catalogs } as unknown as ConstructorParameters<typeof LegacyGenerationAdapter>[1];
  const adapter = new LegacyGenerationAdapter(store, projects, contexts, new Set(), () => records.size + 1);
  try {
    await f.service.observeGenerations((children, parent) => adapter.update(children, parent));
    const input = { ...f.input, requestId: 'retry / arbitrary non-UUID', prompt: 'S'.repeat(50000),
      alternatives: Array.from({ length: 8 }, (_, i) => ({ name: `Candidate ${i}`, prompt: String(i).repeat(50000) })) };
    const receipt = await f.service.genAlternatives(f.parent.id, input);
    expect(await f.service.genAlternatives(f.parent.id, input)).toEqual(receipt);
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'thread/fork')).toHaveLength(8));
    await vi.waitFor(() => expect(f.requests.filter(r => r.method === 'turn/start')).toHaveLength(9));
    const run = records.get(receipt.runId)!;
    expect(run.compatibility).toMatchObject({ requestId: input.requestId, candidates: receipt.candidates });
    expect(run.prompts).toHaveLength(8); expect(run.prompts[7].stages.alternative).toHaveLength(50000);
    expect(run.prompts[0].stages.shared).toBe(input.prompt);
    expect(run.inputs.source.history.headId).toBe(f.c.canvasViews().saved[f.viewId].finalCheckpointId);
    const context = await contexts.read(run.agentContextId);
    expect(JSON.stringify(context.snapshot)).toContain('Try three different layouts exactly as described.');
    const child = await f.service.get(receipt.candidates[0].chatId);
    f.notify({ method: 'turn/completed', params: { threadId: child.threadId, turn: { id: child.turnId, status: 'completed' } } });
    await vi.waitFor(() => expect(records.get(run.id)!.cells[0].canvasId).toBeTruthy());
    for (const candidate of receipt.candidates.slice(1)) await f.service.cancelGeneration(candidate.chatId);
    await vi.waitFor(() => expect(records.get(run.id)!.status).toBe('partial'));
    const final = records.get(run.id)!;
    expect(final.cells.filter(cell => cell.canvasId)).toHaveLength(1);
    expect(final.cells.filter(cell => cell.status === 'cancelled')).toHaveLength(7);
    expect(final.agentContextId).toBe(run.agentContextId);
    expect(Object.values(final.outputSnapshots!)[0].generated.promptStages).toEqual(run.prompts[0].stages);
    expect(f.c.canvasViews().saved[receipt.candidates[0].viewId].generation?.status).toBe('finished');
    expect(f.requests.filter(r => r.method === 'thread/start')).toHaveLength(1); // Original parent only.
    f.c.applyUpdate(f.c.getSnapshot().version, [{ method: 'replace', nodeId: 'grid:overview', ascii: 'Saved later' }]);
    f.c.canvasView(f.c.getSnapshot().version, { operation: 'save', viewId: f.viewId });
    const replayId = await f.service.rerunAlternatives(final, 'rerun / arbitrary');
    const replay = records.get(replayId)!;
    expect(replay.parentRunId).toBe(final.id); expect(replay.agentContextId).toBe(final.agentContextId);
    expect(documentFromHistory(replay.inputs.source.history).scene.contents.overview.content.ascii).toBe('Original');
    expect(replay.inputs.source.source.checkpointId).toBe(final.inputs.source.source.checkpointId);
    expect(f.c.canvasViews().saved[replay.compatibility!.candidates[0].viewId].forkCheckpointId).toBe(final.inputs.source.source.checkpointId);
    for (const candidate of replay.compatibility!.candidates) await f.service.cancelGeneration(candidate.chatId);
    for (const request of f.requests.filter(r => r.method === 'thread/fork')) expect(request.params.model).toBe('model-x');
  } finally { f.service.dispose(); await rm(root, { recursive: true, force: true }); }
});
